```csharp
using System;
using System.Net;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Text;
using System.Threading.Tasks;

class Program
{
    static async Task Main(string[] args)
    {
        var server = new HttpListener();
        server.Prefixes.Add("http://*:8080/");
        server.Start();

        Console.WriteLine("Server started. Press Ctrl+C to stop.");
        while (true)
        {
            var context = await server.GetContextAsync();
            var request = context.Request;
            var response = context.Response;

            if (request.HttpMethod == "GET")
            {
                var responseString = "hello";
                var responseBytes = Encoding.UTF8.GetBytes(responseString);

                response.ContentLength64 = responseBytes.Length;
                response.ContentType = "text/plain";
                response.ContentEncoding = Encoding.UTF8;

                await response.Content.WriteAsync(responseBytes, 0, responseBytes.Length);
                response.Close();
            }
            else
            {
                response.StatusCode = (int)HttpStatusCode.BadRequest;
                response.StatusDescription = "Method not allowed";
                response.Close();
            }
        }
    }
}
```

Ce code crée un serveur HTTP qui écoute sur le port 8080 et qui affiche "hello" sur la page. Il utilise la classe `HttpListener` pour créer le serveur HTTP. Pour chaque requête, il vérifie si la méthode est GET, et si c'est le cas, il envoie une réponse avec le contenu "hello". Sinon, il envoie une réponse avec le statut "Method not allowed".

Vous pouvez compiler et exécuter ce code avec `dotnet build` et `dotnet run`.

